import Foundation
import CommonCrypto

// Secure message framing protocol for multi-tenant IPC
// Frame format: [4-byte length][1-byte type][1-byte tenant][payload][32-byte HMAC]

struct FrameHeader {
    let payloadLength: UInt32
    let messageType: UInt8
    let tenantId: UInt8
}

class SecureFrameProcessor {
    private let processingQueue = DispatchQueue(label: "com.ipc.frameprocessor")
    private var tenantKeys: [UInt8: Data] = [:]
    private var frameBuffer: Data = Data()
    private let maxPayloadSize: UInt32 = 65536
    private var processedFrames: [(tenantId: UInt8, payload: Data)] = []

    func registerTenant(id: UInt8, secretKey: Data) {
        processingQueue.sync {
            guard secretKey.count == 32 else { return }
            self.tenantKeys[id] = secretKey
        }
    }

    func receiveData(_ data: Data) {
        processingQueue.sync {
            self.frameBuffer.append(data)
            self.processAvailableFrames()
        }
    }

    private func processAvailableFrames() {
        // Must be called on processingQueue
        while frameBuffer.count >= 6 {
            // Parse header
            let payloadLength = frameBuffer.withUnsafeBytes { ptr -> UInt32 in
                ptr.load(fromByteOffset: 0, as: UInt32.self).littleEndian
            }
            let messageType = frameBuffer[4]
            let tenantId = frameBuffer[5]

            // Validate payload size limit FIRST before any size calculations
            guard payloadLength <= maxPayloadSize else {
                // Skip malformed frame - advance past header
                frameBuffer = frameBuffer.advanced(by: 6)
                continue
            }

            // Calculate total frame size: header(6) + payload + hmac(32)
            // Safe because payloadLength <= 65536, so no overflow possible
            let totalFrameSize = 6 + Int(payloadLength) + 32

            // Wait for complete frame
            guard frameBuffer.count >= totalFrameSize else { break }

            // Extract payload and HMAC
            let payloadStart = 6
            let payloadEnd = payloadStart + Int(payloadLength)
            let hmacStart = payloadEnd
            let hmacEnd = hmacStart + 32

            let payload = frameBuffer.subdata(in: payloadStart..<payloadEnd)
            let hmac = frameBuffer.subdata(in: hmacStart..<hmacEnd)

            // Verify HMAC
            guard let key = tenantKeys[tenantId] else {
                frameBuffer = frameBuffer.advanced(by: totalFrameSize)
                continue
            }

            let headerAndPayload = frameBuffer.subdata(in: 0..<payloadEnd)
            guard verifyHMAC(data: headerAndPayload, expectedMAC: hmac, key: key) else {
                frameBuffer = frameBuffer.advanced(by: totalFrameSize)
                continue
            }

            // Tenant isolation: only deliver to registered tenant
            processedFrames.append((tenantId: tenantId, payload: payload))

            // Advance buffer
            frameBuffer = frameBuffer.advanced(by: totalFrameSize)
        }
    }

    private func verifyHMAC(data: Data, expectedMAC: Data, key: Data) -> Bool {
        var computedMAC = Data(count: Int(CC_SHA256_DIGEST_LENGTH))
        computedMAC.withUnsafeMutableBytes { macPtr in
            data.withUnsafeBytes { dataPtr in
                key.withUnsafeBytes { keyPtr in
                    CCHmac(
                        CCHmacAlgorithm(kCCHmacAlgSHA256),
                        keyPtr.baseAddress!, key.count,
                        dataPtr.baseAddress!, data.count,
                        macPtr.baseAddress!
                    )
                }
            }
        }
        // Constant-time comparison
        return constantTimeCompare(computedMAC, expectedMAC)
    }

    private func constantTimeCompare(_ a: Data, _ b: Data) -> Bool {
        guard a.count == b.count else { return false }
        var result: UInt8 = 0
        for i in 0..<a.count {
            result |= a[i] ^ b[i]
        }
        return result == 0
    }

    func getMessages(forTenant tenantId: UInt8) -> [Data] {
        return processingQueue.sync {
            return self.processedFrames
                .filter { $0.tenantId == tenantId }
                .map { $0.payload }
        }
    }
}
